# 数字三角形 DP
def dp(triangle):
    r = len(triangle)
    f = [row[:] for row in triangle]  # f[i][j] = 从顶到(i,j)最大和
    for i in range(1, r):
        for j in range(i + 1):
            best = f[i-1][j] if j < i else -inf
            if j > 0: best = max(best, f[i-1][j-1])
            f[i][j] += best
    return max(f[r-1])
